"""Check Rappen's translations against the strings Frappe extracts from the app.

Usage: python check_translations.py <generated main.pot> <rappen locale dir> [<locale dir of another app> ...]

The .pot is generated by ``bench generate-pot-file --app rappen`` in CI, so it contains every string that
Frappe extracts from Python, JavaScript, Jinja templates and doctype JSON. Two rules:

1. Every string needs a translation in de, fr and it, either in Rappen's catalog or, for generic labels such
   as «Company», in the catalog of Frappe or ERPNext.
2. Rappen must not translate a string without context that Frappe or ERPNext translate already. Frappe merges
   the catalogs of all apps, so Rappen's translation would replace theirs in the whole user interface. Generic
   words that Rappen needs in its own wording carry the context «Rappen»: ``_("Date", context="Rappen")``.
"""

import ast
import sys
from pathlib import Path

LANGUAGES = ("de", "fr", "it")


def read_catalog(path: Path) -> dict[tuple[str, str], str]:
	"""(msgctxt, msgid) to msgstr, for .po or .pot files without plural forms."""
	entries: dict[tuple[str, str], str] = {}
	if not path.exists():
		return entries
	current = {"msgctxt": "", "msgid": "", "msgstr": ""}
	key = None

	def flush():
		if current["msgid"]:
			entries[(current["msgctxt"], current["msgid"])] = current["msgstr"]

	for line in path.read_text(encoding="utf-8").splitlines():
		line = line.strip()
		if not line or line.startswith("#"):
			continue
		keyword = next((k for k in ("msgctxt", "msgid", "msgstr") if line.startswith(k + " ")), None)
		if keyword:
			# A new entry starts with msgctxt, or with msgid when the previous entry is complete
			if keyword == "msgctxt" or (keyword == "msgid" and key == "msgstr"):
				flush()
				current = {"msgctxt": "", "msgid": "", "msgstr": ""}
			key = keyword
			current[key] = ast.literal_eval(line[len(keyword) + 1 :])
		elif line.startswith('"') and key:
			current[key] += ast.literal_eval(line)
	flush()
	return entries


def main() -> int:
	pot, locale, others = Path(sys.argv[1]), Path(sys.argv[2]), [Path(p) for p in sys.argv[3:]]
	wanted = sorted(read_catalog(pot))
	problems = 0
	for language in LANGUAGES:
		own = read_catalog(locale / f"{language}.po")
		theirs: dict[tuple[str, str], str] = {}
		for other in others:
			theirs.update({k: v for k, v in read_catalog(other / f"{language}.po").items() if v})

		for context, msgid in wanted:
			if not own.get((context, msgid)) and not theirs.get((context, msgid)):
				where = f" (context {context!r})" if context else ""
				print(f"{language}: missing translation for {msgid!r}{where}")
				problems += 1
		for context, msgid in own:
			if (
				not context
				and (context, msgid) in theirs
				and own[(context, msgid)] != theirs[(context, msgid)]
			):
				print(
					f"{language}: {msgid!r} is translated by Frappe or ERPNext already; drop it from Rappen's "
					f"catalog or give it the context 'Rappen'"
				)
				problems += 1
	print(f"{len(wanted)} strings, {problems} problems")
	return 1 if problems else 0


if __name__ == "__main__":
	sys.exit(main())
